class NumMatrix {
  private final int[][] tree, values;
  private final int rows, cols;

  public NumMatrix(int[][] matrix) {
    rows = matrix.length;
    cols = matrix[0].length;
    tree = new int[rows + 1][cols + 1];
    values = new int[rows][cols];
    for (int i = 0; i < rows; i++) {
      for (int j = 0; j < cols; j++) update(i, j, matrix[i][j]);
    }
  }

  public void update(int row, int col, int val) {
    int delta = val - values[row][col];
    values[row][col] = val;
    for (int i = row + 1; i <= rows; i += i & -i) {
      for (int j = col + 1; j <= cols; j += j & -j) tree[i][j] += delta;
    }
  }

  public int sumRegion(int row1, int col1, int row2, int col2) {
    return prefix(row2 + 1, col2 + 1)
        - prefix(row1, col2 + 1)
        - prefix(row2 + 1, col1)
        + prefix(row1, col1);
  }

  private int prefix(int row, int col) {
    int sum = 0;
    for (int i = row; i > 0; i -= i & -i) {
      for (int j = col; j > 0; j -= j & -j) sum += tree[i][j];
    }
    return sum;
  }
}

